     9	/** How often `tick()` runs once the scheduler is started. */
    10	const TICK_INTERVAL_MS = 60_000;
    11	
    12	/** Minimum gap between two runs of the same job kind, in minutes. */
    13	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
    14	  "digest-email": 60,
    15	  "overdue-issues": 60,
    16	  "webhook-delivery": 1,
    17	  "usage-rollup": 15,
    18	  "search-reindex": 1_440,
    19	  "cleanup-archived": 1_440,
    20	  "trial-expiry": 360,
    21	};
    22	
    23	const logger = createLogger("job-scheduler");
    24	
    25	let timer: ReturnType<typeof setInterval> | null = null;
    26	const lastRunAt = new Map<JobKind, number>();
    27	
    28	/**
    29	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
    30	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
    31	 * that misses the last tick.
    32	 */
    33	export function startScheduler(): void {
    34	  if (timer !== null) return;
    35	
    36	  timer = setInterval(() => {
    37	    void tick(new Date()).catch((error: unknown) => {
    38	      logger.error("scheduler tick failed", {
    39	        reason: error instanceof Error ? error.message : String(error),
    40	      });
    41	    });
    42	  }, TICK_INTERVAL_MS);
    43	
    44	  timer.unref?.();
    45	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
    46	}
    47	
    48	export function stopScheduler(): void {
    49	  if (timer === null) return;
    50	  clearInterval(timer);
    51	  timer = null;
    52	  lastRunAt.clear();
    53	}
