     1	/**
     2	 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
     3	 * digest-window arithmetic.
     4	 *
     5	 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
     6	 * a SQLite text column). Nothing outside this module constructs a `Date` from
     7	 * a stored value — going through `parseIso()` keeps the "what if it is
     8	 * malformed" answer in one place.
     9	 */
    10	import type { IsoTimestamp } from "@/types/common";
    11	import { toIsoTimestamp } from "@/types/common";
    12	
    13	const MINUTE_MS = 60_000;
    14	const HOUR_MS = 60 * MINUTE_MS;
    15	const DAY_MS = 24 * HOUR_MS;
    16	const WEEK_MS = 7 * DAY_MS;
    17	
    18	export function now(): IsoTimestamp {
    19	  return toIsoTimestamp(new Date());
    20	}
    21	
    22	/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
    23	export function parseIso(value: IsoTimestamp): Date {
    24	  const date = new Date(value);
    25	  if (Number.isNaN(date.getTime())) {
    26	    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
    27	  }
    28	  return date;
    29	}
    30	
    31	function plural(count: number, unit: string): string {
    32	  return `${count} ${unit}${count === 1 ? "" : "s"}`;
    33	}
    34	
    35	/**
    36	 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
    37	 * issue cards and comment headers all use.
    38	 */
    39	export function formatRelative(
    40	  value: IsoTimestamp,
    41	  reference: Date = new Date(),
    42	): string {
    43	  const deltaMs = parseIso(value).getTime() - reference.getTime();
    44	  const past = deltaMs < 0;
    45	  const abs = Math.abs(deltaMs);
    46	
    47	  const phrase = ((): string => {
    48	    if (abs < MINUTE_MS) return "just now";
    49	    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    50	    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    51	    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    52	    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    53	    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    54	    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
    55	  })();
    56	
    57	  if (phrase === "just now") return phrase;
    58	  return past ? `${phrase} ago` : `in ${phrase}`;
    59	}
    60	
    61	/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
    62	export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
    63	  return new Intl.DateTimeFormat("en-GB", {
    64	    day: "2-digit",
    65	    month: "short",
    66	    year: "numeric",
    67	    timeZone: timezone,
    68	  }).format(parseIso(value));
    69	}
    70	
    71	/** True when a due date exists and has already passed. */
    72	export function isOverdue(
    73	  dueAt: IsoTimestamp | null,
    74	  reference: Date = new Date(),
    75	): boolean {
    76	  if (dueAt === null) return false;
    77	  return parseIso(dueAt).getTime() < reference.getTime();
    78	}
    79	
    80	export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
    81	  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
    82	}
    83	
    84	/**
    85	 * The 24-hour window a digest covers, ending at today's `digestHourUtc`. If
    86	 * that hour has not arrived yet on `reference`'s day, the window is the one
    87	 * that ended yesterday — so a job run early never mails an empty digest and
    88	 * then skips the real one.
    89	 */
    90	export function digestWindow(
    91	  digestHourUtc: number,
    92	  reference: Date,
    93	): { start: IsoTimestamp; end: IsoTimestamp } {
    94	  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    95	    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
    96	  }
    97	
    98	  const end = new Date(
    99	    Date.UTC(
   100	      reference.getUTCFullYear(),
   101	      reference.getUTCMonth(),
   102	      reference.getUTCDate(),
   103	      digestHourUtc,
   104	      0,
   105	      0,
   106	      0,
   107	    ),
   108	  );
   109	  if (end.getTime() > reference.getTime()) {
   110	    end.setUTCDate(end.getUTCDate() - 1);
   111	  }
   112	
   113	  return {
   114	    start: toIsoTimestamp(new Date(end.getTime() - DAY_MS)),
   115	    end: toIsoTimestamp(end),
   116	  };
   117	}
