     1	/**
     2	 * Server-side flag context construction and the org-level override toggle.
     3	 *
     4	 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
     5	 */
     6	import { emit } from "@/lib/event-bus";
     7	import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
     8	import { assertCan } from "@/lib/permissions";
     9	import { getFlagDefinition } from "@/config/feature-flags";
    10	import * as orgRepo from "@/server/repositories/organization-repository";
    11	import { actorEnvelope, orgResource, requireFound } from "./_support";
    12	import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
    13	import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
    14	import type { Actor } from "@/types/member";
    15	import type { Organization } from "@/types/organization";
    16	
    17	/**
    18	 * Builds the evaluation context every `isEnabled()` call needs. Both halves
    19	 * are nullable so marketing pages — no session, no org — can still ask about
    20	 * a flag and get the free-plan answer.
    21	 */
    22	export function buildFlagContext(
    23	  actor: Actor | null,
    24	  org: Organization | null,
    25	): FlagContext {
    26	  return {
    27	    orgId: org?.id ?? actor?.orgId ?? null,
    28	    userId: actor?.userId ?? null,
    29	    plan: org?.plan ?? "free",
    30	    role: actor?.role ?? null,
    31	    overrides: org?.settings.enabledFlagOverrides,
    32	  };
    33	}
    34	
    35	/**
    36	 * The serialisable snapshot the dashboard layout hands to the client provider,
    37	 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
    38	 * the server.
    39	 */
    40	export function getSnapshot(
    41	  actor: Actor,
    42	  org: Organization,
    43	): FeatureFlagSnapshot {
    44	  return snapshotFlags(buildFlagContext(actor, org));
    45	}
    46	
    47	/**
    48	 * Adds or removes an org-level override. Only flags declared `overridable`
    49	 * accept one — a flag gated purely on plan cannot be switched on by an admin,
    50	 * which is what keeps the plan boundary meaningful.
    51	 */
    52	export async function toggleFlag(
    53	  actor: Actor,
    54	  input: ToggleFeatureFlagInput,
    55	): Promise<Organization> {
    56	  assertCan(actor, "org:manage_flags", orgResource(input.orgId));
    57	
    58	  const org = requireFound(
    59	    await orgRepo.findOrgById(input.orgId),
    60	    "Organization",
    61	    input.orgId,
    62	  );
    63	
    64	  const definition = getFlagDefinition(input.flag);
    65	  if (!definition.overridable) {
    66	    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
    67	  }
    68	
    69	  const current = new Set(org.settings.enabledFlagOverrides);
    70	  if (input.enabled) {
    71	    current.add(input.flag);
    72	  } else {
    73	    current.delete(input.flag);
    74	  }
    75	
    76	  const updated = await orgRepo.updateOrg(input.orgId, {
    77	    orgId: input.orgId,
    78	    settings: { enabledFlagOverrides: [...current] },
    79	  });
    80	
    81	  await emit("flag.toggled", {
    82	    ...actorEnvelope(actor),
    83	    flag: input.flag,
    84	    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
    85	  });
    86	
    87	  return updated;
    88	}
=== lib/feature-flags ===
     1	import {
     2	  FEATURE_FLAG_DEFINITIONS,
     3	  FEATURE_FLAG_KEYS,
     4	} from "@/config/feature-flags";
     5	import { planAtLeast } from "@/config/plan-limits";
     6	import { ROLE_RANK } from "@/types/member";
     7	import type {
     8	  FeatureFlagKey,
     9	  FeatureFlagSnapshot,
    10	  FlagContext,
    11	} from "@/types/feature-flag";
    12	
    13	/**
    14	 * Feature-flag evaluation, shared verbatim by server and client.
    15	 *
    16	 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
    17	 * directly; the dashboard layout serialises `snapshotFlags()` into the client
    18	 * provider so `useFeatureFlag()` answers the same way without a round trip.
    19	 * Both sides must agree — never re-implement a strategy at a call site.
    20	 */
    21	export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
    22	  const definition = FEATURE_FLAG_DEFINITIONS[flag];
    23	  if (!definition) return false;
    24	
    25	  if (definition.overridable && ctx.overrides?.includes(flag)) {
    26	    return true;
    27	  }
    28	
    29	  const strategy = definition.strategy;
    30	  switch (strategy.kind) {
    31	    case "off":
    32	      return false;
    33	    case "on":
    34	      return true;
    35	    case "plan":
    36	      return planAtLeast(ctx.plan, strategy.minPlan);
    37	    case "role":
    38	      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    39	    case "percentage":
    40	      return bucketOf(flag, ctx) < strategy.percent;
    41	    default:
    42	      return false;
    43	  }
    44	}
    45	
    46	/** Evaluates every flag at once, for handoff to the client provider. */
    47	export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
    48	  const snapshot = {} as Record<FeatureFlagKey, boolean>;
    49	  for (const key of FEATURE_FLAG_KEYS) {
    50	    snapshot[key] = isEnabled(key, ctx);
    51	  }
    52	  return snapshot;
    53	}
    54	
    55	/** Throwing guard for server actions gated behind a flag. */
    56	export class FeatureDisabledError extends Error {
    57	  readonly code = "forbidden" as const;
    58	
    59	  constructor(readonly flag: FeatureFlagKey) {
    60	    super(`Feature "${flag}" is not enabled for this organization.`);
    61	    this.name = "FeatureDisabledError";
    62	  }
    63	}
    64	
    65	export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
    66	  if (!isEnabled(flag, ctx)) {
    67	    throw new FeatureDisabledError(flag);
    68	  }
    69	}
    70	
    71	/**
    72	 * Deterministic 0–99 bucket for percentage rollouts. Stable per
    73	 * (flag, org, user) so a viewer never sees the feature flicker.
    74	 */
    75	function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
    76	  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
    77	  let hash = 2_166_136_261;
    78	  for (let i = 0; i < seed.length; i += 1) {
    79	    hash ^= seed.charCodeAt(i);
    80	    hash = Math.imul(hash, 16_777_619);
    81	  }
    82	  return Math.abs(hash) % 100;
    83	}

